//! 🧬️ Window preview retains one original press projection and the installed semantic producer across granted turns.
use super::*;
use semio_framework_value::retained_clone::{RetainedOwnedProjection,RetainedCloneClose};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use store::ErasedSnapshotRetirement as _;
use store::os_store::{ArtifactDerivedOperation,ArtifactDerivedOperationMode,snapshot_read::{ArtifactDerivedSnapshot,admit_original_snapshot_alias}};
/// 🧳️ Original native preview state keeps source and displaced owners until exact closure.
pub(super) struct WindowSemanticPreview<O:WindowConfigOwner>{
 base:Option<ArtifactDerivedSnapshot<O::State>>,input:Option<RetainedOwnedProjection<O::Mutation>>,producer:Option<ArtifactDerivedOperation<O::State,O::Mutation>>,displaced:Option<ArtifactDerivedSnapshot<O::State>>,active:Option<Box<dyn store::ErasedSnapshotRetirement>>,
 snapshots:Option<Arc<dyn store::ArtifactOwnedValueRetirementFactory<O::State>>>,mutations:Option<Arc<dyn store::ArtifactOwnedValueRetirementFactory<O::Mutation>>>,factory_close:[Option<semio_framework_value::FactoryAuthority>;2],applied:bool,cancelled:bool,
}
fn preview_funds(g:RetainedCloneGrant,d:RetirementDemand)->bool{semio_framework_value::retained_clone::retained_clone_grant_admits(g,d)}
impl<O:WindowConfigOwner> WindowSemanticPreview<O>{
 pub(super) fn birth_demand()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()+size_of::<ArtifactDerivedSnapshot<O::State>>()+2*size_of::<Arc<dyn semio_framework_value::FactoryRetirement>>(),depth:1,..Default::default()}}
 pub(super) fn begin(store:&WindowConfigStore<O>,g:RetainedCloneGrant)->Result<Option<(Self,RetainedCloneProgress)>,ValueError>{let d=Self::birth_demand();if !preview_funds(g,d){return Ok(None);}Ok(Some((Self{base:Some(store.derived_snapshot_head()),input:None,producer:None,displaced:None,active:None,snapshots:Some(Arc::clone(store.owned_snapshot_retirement_factory()?)),mutations:Some(Arc::clone(store.owned_mutation_retirement_factory()?)),factory_close:[None,None],applied:false,cancelled:false},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))}
 pub(super) fn input_demand()->RetirementDemand{let mut d=RetainedOwnedProjection::<O::Mutation>::constructor_demand();d.copy_bytes+=size_of::<bool>();d}
 pub(super) fn admit_input(&mut self,input:&RetainedOwnedProjection<WindowConfigMutation>,g:RetainedCloneGrant)->Result<Option<RetainedCloneProgress>,ValueError>{if self.cancelled||self.input.is_some()||self.producer.is_some()||self.displaced.is_some()||self.active.is_some(){return Ok(None);}let d=Self::input_demand();if !preview_funds(g,d){return Ok(None);}let original=input.borrow()?.get();if original.window_kind_id!=O::WINDOW_KIND_ID||!original.mutation.as_any().is::<O::Mutation>(){return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"window preview requires its actual typed original press operation"));}let child=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-size_of::<bool>(),..g};let(projection,mut p)=input.project(1,|original|original.mutation.as_any().downcast_ref::<O::Mutation>().expect("validated original window operation type"),child)?;self.input=Some(projection);self.applied=false;p.copied_bytes+=size_of::<bool>();Ok(Some(p))}
 pub(super) fn cancel(&mut self){self.cancelled=true;if let Some(owner)=self.producer.as_mut(){owner.cancel();}}
 pub(super) fn needs_cancellation(&self)->bool{!self.cancelled}
 pub(super) fn work_pending(&self)->bool{self.cancelled||self.input.is_some()||self.producer.is_some()||self.displaced.is_some()||self.active.is_some()}
 pub(super) fn leaf_ready(&self)->bool{self.applied&&self.input.is_none()&&self.producer.is_none()&&self.displaced.is_none()&&self.active.is_none()}
 pub(super) fn demand(&self,store:&WindowConfigStore<O>,body:usize)->Result<RetirementDemand,ValueError>{
  if let Some(active)=self.active.as_ref(){return semio_framework_value::factory_ticket_demands(active,body);}
  if let Some(owner)=self.producer.as_ref(){return if owner.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<ArtifactDerivedOperation<O::State,O::Mutation>>>(),depth:1,..Default::default()})}else if owner.is_closing(){owner.next_demand(body)}else if owner.is_finished(){Ok(RetirementDemand{copy_bytes:size_of::<store::os_store::ArtifactReplayPrepared<O::State,O::Mutation>>(),depth:1,..Default::default()})}else{store.derived_operation_demands(owner,body)};}
  if self.displaced.is_some()||(self.cancelled&&self.base.is_some()){return Ok(RetirementDemand{capacity_bytes:store::ArtifactStore::<O::State,O::Mutation>::history_read_retirement_birth_bytes(),depth:1,..Default::default()});}
  if let Some(input)=self.input.as_ref(){return if self.cancelled{if input.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<RetainedOwnedProjection<O::Mutation>>>(),depth:1,..Default::default()})}else{input.close_demand(body)}}else{store.derived_operation_birth_demand(self.base.as_ref().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"window preview original base absent"))?)};}
  if self.cancelled{if self.snapshots.is_some()||self.mutations.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<Arc<dyn semio_framework_value::FactoryRetirement>>(),depth:1,..Default::default()});}if let Some(factory)=self.factory_close.iter().find_map(Option::as_ref){return factory.demands(body);}}
  Ok(Default::default())
 }
 pub(super) fn step(&mut self,store:&WindowConfigStore<O>,g:RetainedCloneGrant,receiving:Option<&mut NativeDecodeControl<'_>>)->Result<RetainedCloneStep,ValueError>{let d=self.demand(store,g.maximum_copy_bytes)?;if !preview_funds(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}
  if self.active.is_some(){return semio_framework_value::close_factory_ticket(&mut self.active,g);}
  if let Some(owner)=self.producer.as_mut(){if owner.terminal_is_empty(){self.producer=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}));}if owner.is_closing(){return owner.close_step(g);}if owner.is_finished(){let Some(((next,messages),p))=store.take_derived_operation(owner,g)?else{return Ok(RetainedCloneStep::Progress(Default::default()));};assert!(messages.is_empty()&&messages.capacity()==0,"provisional semantic producer closes its diagnostics before preview transfer");if let Some(next)=next{self.displaced=self.base.replace(next);}self.applied=true;return Ok(RetainedCloneStep::Progress(p));}let Some(receiving)=receiving else{return Ok(RetainedCloneStep::Progress(Default::default()));};return store.step_derived_operation(owner,g.maximum_copy_bytes,g,receiving,&mut||false);}
  let original=if self.displaced.is_some(){&mut self.displaced}else if self.cancelled&&self.base.is_some(){&mut self.base}else{if let Some(input)=self.input.as_mut(){if self.cancelled{if input.terminal_is_empty(){self.input=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}));}return input.close_step(g);}let p=store.begin_derived_operation(&mut self.producer,self.base.as_ref().unwrap(),&mut self.input,0,ArtifactDerivedOperationMode::Provisional,g)?.unwrap_or_default();return Ok(RetainedCloneStep::Progress(p));}
   if self.cancelled{if let Some(factory)=self.snapshots.take(){self.factory_close[0]=Some(semio_framework_value::FactoryAuthority::new(factory));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}));}if let Some(factory)=self.mutations.take(){self.factory_close[1]=Some(semio_framework_value::FactoryAuthority::new(factory));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}));}if let Some(index)=self.factory_close.iter().position(Option::is_some){let owner=self.factory_close[index].as_mut().unwrap();let step=owner.step(g)?;if owner.terminal_is_empty(){self.factory_close[index]=None;}return Ok(step);}}
   return Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(Default::default())}else{RetainedCloneStep::Progress(Default::default())});};
  let Some((owner,p))=admit_original_snapshot_alias(original,self.snapshots.as_ref().unwrap(),self.mutations.as_ref().unwrap(),g)?else{return Ok(RetainedCloneStep::Progress(Default::default()));};self.active=Some(owner);Ok(RetainedCloneStep::Progress(p))
 }
 pub(super) fn take_base(&mut self,g:RetainedCloneGrant)->Result<Option<(ArtifactDerivedSnapshot<O::State>,RetainedCloneProgress)>,ValueError>{if !self.leaf_ready()||self.cancelled{return Ok(None);}let d=RetirementDemand{copy_bytes:size_of::<ArtifactDerivedSnapshot<O::State>>(),depth:1,..Default::default()};if !preview_funds(g,d){return Ok(None);}let Some(base)=self.base.take()else{return Ok(None)};self.cancelled=true;Ok(Some((base,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))}
 pub(super) fn terminal_is_empty(&self)->bool{self.cancelled&&self.base.is_none()&&self.input.is_none()&&self.producer.is_none()&&self.displaced.is_none()&&self.active.is_none()&&self.snapshots.is_none()&&self.mutations.is_none()&&self.factory_close.iter().all(Option::is_none)}
}
impl<O:WindowConfigOwner> Drop for WindowSemanticPreview<O>{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"window semantic preview dropped original owners before paid closure");}}

